package com.bank.restart;

// A container run: how it ended (exit code, reason) and its last log line.
public class ContainerInstance {
    public enum Reason { OOM_KILLED, LIVENESS_FAIL, BAD_ENTRYPOINT, CLEAN_EXIT, HEALTHY }
    private final String name;
    private final Reason reason;
    private final int exitCode;
    private final String lastLog;

    public ContainerInstance(String name, Reason reason, int exitCode, String lastLog) {
        this.name = name;
        this.reason = reason;
        this.exitCode = exitCode;
        this.lastLog = lastLog;
    }
    public String getName()   { return name; }
    public Reason getReason() { return reason; }
    public int getExitCode()  { return exitCode; }
    public String getLastLog(){ return lastLog; }
    public boolean healthy()  { return reason == Reason.HEALTHY; }
}
