package com.bank.restart;

import java.util.logging.Logger;

// Reads logs, exit code, reason to classify why the container restarts.
public class Diagnoser {
    private static final Logger log = Logger.getLogger(Diagnoser.class.getName());

    public String diagnose(ContainerInstance c) {
        // Step 1: read the previous logs.
        log.info(() -> "kubectl logs " + c.getName() + " --previous -> " + c.getLastLog());
        // Step 2: inspect the exit code + reason.
        log.info(() -> "kubectl describe -> exitCode=" + c.getExitCode()
                + " reason=" + c.getReason());
        // Step 3: classify + prescribe the fix.
        return switch (c.getReason()) {
            case OOM_KILLED -> "ROOT CAUSE: OOMKilled (exit 137). FIX: raise memory limit "
                    + "or align JVM max heap to the cgroup limit / fix leak";
            case LIVENESS_FAIL -> "ROOT CAUSE: liveness probe failing. FIX: correct probe "
                    + "path/port or add a startup probe for slow startup";
            case BAD_ENTRYPOINT -> "ROOT CAUSE: bad entrypoint / missing config. FIX: correct "
                    + "ENTRYPOINT or provide the missing secret/config";
            case CLEAN_EXIT -> "ROOT CAUSE: process exited 0 (should be long-running). "
                    + "FIX: keep the main process in the foreground";
            case HEALTHY -> "No fault: container is healthy";
        };
    }
}
