package com.bank.restart;

import java.util.logging.Logger;

// Restarts a failing container with increasing backoff (CrashLoopBackOff).
public class RestartController {
    private static final Logger log = Logger.getLogger(RestartController.class.getName());
    private final Diagnoser diagnoser = new Diagnoser();

    public void supervise(ContainerInstance c, int maxRestarts) {
        int backoffSeconds = 1;
        for (int attempt = 1; attempt <= maxRestarts && !c.healthy(); attempt++) {
            final int a = attempt, b = backoffSeconds;
            log.warning(() -> "Container '" + c.getName() + "' exited; restart #" + a
                    + " after " + b + "s backoff (CrashLoopBackOff)");
            backoffSeconds = Math.min(backoffSeconds * 2, 300); // cap backoff
        }
        if (!c.healthy()) {
            String cause = diagnoser.diagnose(c);
            log.severe(cause);
        } else {
            log.info(() -> "Container '" + c.getName() + "' is healthy, no restarts needed");
        }
    }
}
