package com.bank.restart;

import java.util.logging.*;

public class RestartDebugDemo {
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new RestartLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RestartController controller = new RestartController();

        // Case 1: OOMKilled under peak transfer load.
        controller.supervise(new ContainerInstance("transfer-oom",
                ContainerInstance.Reason.OOM_KILLED, 137,
                "java.lang.OutOfMemoryError: Java heap space"), 3);

        // Case 2: liveness probe pointing at the wrong path.
        controller.supervise(new ContainerInstance("transfer-probe",
                ContainerInstance.Reason.LIVENESS_FAIL, 143,
                "Started on 8080; liveness GET /healthz returned 404"), 3);

        // Case 3: missing DB password secret -> throws at startup.
        controller.supervise(new ContainerInstance("transfer-config",
                ContainerInstance.Reason.BAD_ENTRYPOINT, 1,
                "IllegalStateException: required property DB_PASSWORD not set"), 3);

        // Case 4: a healthy container (for contrast).
        controller.supervise(new ContainerInstance("transfer-ok",
                ContainerInstance.Reason.HEALTHY, 0, "Started transfer-service on 8080"), 3);
    }
}

// ─── Would be in RestartLogFormatter.java in a real project ───
class RestartLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
